/* cppi::4a7451c17ca0864f6bef505ab691aef475f5271d64e0e546e9a5943402fa74ca */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-12' and business_date <= date '2025-06-12' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

/* cppi::7fbda5497d918812497a4098ebb0ba7e4a586e455a80416495bdaf17896ef0e1 */
